import pennylane as qml
from pennylane import numpy as np

dev = qml.device("default.qubit", wires=4)

@qml.qnode(dev)
def qaoa_circuit(gammas, betas, hamiltonian):
    qml.QAOAAnsatz(hamiltonian, qml.RX, len(gammas))
    # Parameters are optimized using a classical optimizer
    return qml.expval(hamiltonian)

